<?php
declare(strict_types=1);
namespace BYPCMS\Core;
require_once __DIR__.'/Content.php';
require_once __DIR__.'/Journal.php';
require_once __DIR__.'/BusinessView.php';

/** Independent Mono presentation; content, privacy and enquiries use Business. */
final class Mono {
    public static function published(array $page):bool {return BusinessView::published($page);}
    public static function imageSources(string $url):string {
        if(preg_match('#^/themes/mono/assets/(identity|digital|object|studio)\.webp$#D',$url)){
            $stem=substr($url,0,-5);$e=[Content::class,'e'];
            return ' srcset="'.$e(Content::asset($stem.'-480.webp')).' 480w, '.$e(Content::asset($stem.'-960.webp')).' 960w, '.$e(Content::asset($url)).' 1440w" sizes="(max-width:650px) 100vw, (max-width:1000px) 90vw, 1200px"';
        }
        return Content::imageSet($url);
    }
    private static function initials(string $name):string {
        $parts=preg_split('/\s+/u',trim($name));return mb_strtoupper(implode('',array_map(fn($v)=>mb_substr($v,0,1),array_slice($parts,0,2))));
    }
    public static function render(array $records,array $settings,string $path,string $base='',array $options=[]):void {
        $e=[Content::class,'e'];$path=trim($path,'/');if($path==='home')$path='';
        $snapshot=$options['snapshot']??'';$preview=!empty($options['preview']);
        $pages=array_values(array_filter($records,fn($p)=>in_array($p['kind']??'page',['page','service','project','person'],true)&&($preview||self::published($p))));
        foreach($pages as &$p)$p+=['id'=>0,'kind'=>'page','slug'=>'','title'=>'','excerpt'=>'','content'=>'','blocks'=>[],'cover'=>''];unset($p);
        $find=static function(string $slug)use($pages){foreach($pages as $p)if(trim($p['slug'],'/')===$slug)return $p;return null;};
        $kind=static fn(string $kind)=>array_values(array_filter($pages,fn($p)=>$p['kind']===$kind));
        $services=$kind('service');$projects=$kind('project');$team=$kind('person');
        $home=$find('home');$about=$find('about');$privacy=$find('privacy');
        $href=static function(string $route,array $query=[])use($base,$snapshot){if($snapshot)$query['snapshot']=$snapshot;return $base.$route.($query?'?'.http_build_query($query):'');};
        $asset=static fn(string $file)=>Content::asset('/themes/mono/'.$file);
        $routes=[''=>'home','services'=>'services','projects'=>'projects','team'=>'team','contact'=>'contact','search'=>'search','request-success'=>'success'];
        $page=$path?$find($path):$home;$mode=$routes[$path]??($page?'detail':'404');
        if($mode==='success'&&empty($options['receipt']))$mode='404';
        $q='';$service=0;$number=1;$order='recent';$error='';
        try{
            $q=BusinessView::query('q');$service=BusinessView::number('service');$number=BusinessView::number('page');
            $order=BusinessView::query('order',20)?:'recent';if(!in_array($order,['recent','name'],true))throw new \RuntimeException('Выберите порядок из списка.');
        }catch(\RuntimeException $x){$error=$x->getMessage();}
        $status=$options['http_status']??($error?400:($mode==='404'?404:200));http_response_code($status);
        header('Content-Type: text/html; charset=utf-8');header('X-Content-Type-Options: nosniff');
        header("Content-Security-Policy: default-src 'self'; img-src 'self' https: data:; style-src 'self' 'unsafe-inline'; font-src 'self'; script-src 'self'; frame-ancestors 'self'; base-uri 'none'; form-action 'self'");
        if($base||$preview||$status!==200||in_array($mode,['search','contact','success'],true)){header('X-Robots-Tag: noindex, nofollow');header('Cache-Control: no-store');}
        $name=$settings['site_name']??'Mono';$tagline=$settings['tagline']??'Меньше шума. Больше смысла.';
        $titles=['home'=>$tagline,'services'=>'От задачи к системе.','projects'=>'Работы, которые говорят.','team'=>'Люди за работой.','contact'=>'Начнём с разговора.','search'=>'Найти главное.','success'=>'Заявка сохранена','404'=>'Здесь пока пусто.'];
        $title=$page&&in_array($mode,['home','detail'],true)?(($page['seo_title']??'')?:($mode==='home'?$tagline:$page['title'])):$titles[$mode];
        $description=$page&&in_array($mode,['home','detail'],true)?(($page['seo_description']??'')?:$page['excerpt']):$tagline;
        $canonical=Content::url($page['canonical']??'')?:rtrim($settings['site_url']??'','/').$base.'/'.($path?$path.'/':'');
        $accent=preg_match('/^#[0-9a-f]{6}$/i',$settings['accent']??'')?$settings['accent']:'#d5ef62';
        $rgb=array_map(fn($i)=>hexdec(substr($accent,$i,2))/255,[1,3,5]);$linear=array_map(fn($v)=>$v<=.04045?$v/12.92:pow(($v+.055)/1.055,2.4),$rgb);$luminance=.2126*$linear[0]+.7152*$linear[1]+.0722*$linear[2];$onAccent=$luminance>.179?'#151515':'#ffffff';
        $image=static function(array $p,bool $eager=false)use($e){$src=Content::imageUrl($p['cover']??'');if(!$src)return '<div class="mo-noimage">Изображение не добавлено</div>';return '<img src="'.$e(Content::asset($src)).'"'.self::imageSources($src).' alt="'.$e($p['cover_alt']??$p['title']).'" width="1440" height="960" decoding="async" '.($eager?'fetchpriority="high"':'loading="lazy"').'>';};
        $projectCards=static function(array $rows)use($e,$href,$image){foreach($rows as $i=>$p){?>
            <article class="mo-work"><a class="mo-work-image" aria-label="<?= $e('Открыть кейс: '.$p['title']) ?>" href="<?= $e($href('/'.$p['slug'].'/')) ?>"><?= $image($p) ?><span class="mo-round" aria-hidden="true">↗</span></a><div class="mo-work-caption"><div><small><?= $e($p['location']??$p['client']??'ПРОЕКТ') ?></small><h3><a href="<?= $e($href('/'.$p['slug'].'/')) ?>"><?= $e($p['title']) ?></a></h3></div><span><?= $e($p['year']??'') ?></span></div><p><?= $e($p['excerpt']) ?></p></article>
        <?php }};
        $people=static function(array $rows)use($e,$href,$image){foreach($rows as $p){?>
            <article class="mo-person"><a class="mo-person-visual" aria-label="<?= $e('Открыть профиль: '.$p['title']) ?>" href="<?= $e($href('/'.$p['slug'].'/')) ?>"><?php if($p['cover']): echo $image($p);else: ?><span class="mo-monogram" aria-hidden="true"><?= $e(self::initials($p['title'])) ?></span><?php endif ?><span class="mo-round" aria-hidden="true">↗</span></a><small><?= $e($p['role']??'КОМАНДА') ?></small><h3><a href="<?= $e($href('/'.$p['slug'].'/')) ?>"><?= $e($p['title']) ?></a></h3><p><?= $e($p['excerpt']) ?></p></article>
        <?php }};
        $crumb=static function(string $label,?string $section=null)use($e,$href){?><nav class="mo-crumb" aria-label="Хлебные крошки"><a href="<?= $e($href('/')) ?>">Главная</a><?php if($section): ?><span>/</span><a href="<?= $e($href('/'.$section.'/')) ?>"><?= $e(['services'=>'Услуги','projects'=>'Проекты','team'=>'Команда'][$section]) ?></a><?php endif ?><span>/</span><span><?= $e($label) ?></span></nav><?php };
        $social=Content::imageUrl(($page['cover']??'')?:($home['cover']??''));
        ?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $e($title.' — '.$name) ?></title><meta name="description" content="<?= $e($description) ?>"><link rel="canonical" href="<?= $e($canonical) ?>"><meta property="og:title" content="<?= $e($title) ?>"><meta property="og:description" content="<?= $e($description) ?>"><meta property="og:type" content="website"><meta property="og:url" content="<?= $e($canonical) ?>"><?php if($social): ?><meta property="og:image" content="<?= $e(preg_match('#^https?://#',$social)?$social:rtrim($settings['site_url']??'','/').Content::asset($social)) ?>"><?php endif ?><?php if(!empty($page['noindex'])): ?><meta name="robots" content="noindex,follow"><?php endif ?><link rel="stylesheet" href="<?= $e($asset('mono.css')) ?>?v=1.0.0"><script src="<?= $e($asset('mono.js')) ?>?v=1.0.0" defer></script><script src="<?= $e(Content::asset('/themes/journal/business-form.js')) ?>?v=<?= Content::VERSION ?>" defer></script><?php if(($settings['font']??'')!=='system'): ?><link rel="preload" href="<?= $e($asset('assets/manrope.woff2')) ?>" as="font" type="font/woff2" crossorigin><?php endif ?><style>:root{--mo-accent:<?= $e($accent) ?>;--mo-on-accent:<?= $e($onAccent) ?>;--mo-font:<?= ($settings['font']??'')==='system'?'system-ui':'MonoSans' ?>;--mo-heading:<?= ($settings['heading_font']??'')==='georgia'?'Georgia,serif':'var(--mo-font)' ?>}</style></head><body class="mo-site mo-view-<?= $e($mode) ?>"><a class="mo-skip" href="#main">К содержанию</a>
        <?php if(!empty($options['demo'])): ?><div class="mo-demo"><span>BYPCMS Business / Mono</span><span>Демонстрация · тестовые заявки без писем</span></div><?php endif ?>
        <?php if($preview): ?><div class="mo-demo"><span>Предпросмотр · изменения не опубликованы</span><a id="preview-close" href="/manage/">Закрыть ×</a></div><script src="<?= $e(Content::asset('/themes/journal/preview.js')) ?>" defer></script><?php endif ?>
        <header class="mo-header"><div class="mo-wrap mo-header-inner"><a class="mo-logo" href="<?= $e($href('/')) ?>"><?php if(!empty($settings['logo'])): ?><img src="<?= $e(Content::imageUrl($settings['logo'])) ?>" alt="<?= $e($name) ?>"><?php else: echo $e($name); ?><span aria-hidden="true">•</span><?php endif ?></a><button type="button" class="mo-menu-toggle" aria-expanded="false" aria-controls="mono-nav" aria-label="Открыть меню"><span>Меню</span><i aria-hidden="true">+</i></button><nav id="mono-nav" aria-label="Основное меню"><?php foreach(['/projects/'=>'Работы','/services/'=>'Услуги','/about/'=>'Студия','/team/'=>'Команда'] as $url=>$label): if($url==='/about/'&&!$about)continue; ?><a href="<?= $e($href($url)) ?>" <?= $path===trim($url,'/')?'aria-current="page"':'' ?>><?= $label ?></a><?php endforeach ?><?= Journal::menu($settings['menu']??[]) ?><a href="<?= $e($href('/search/')) ?>" class="mo-search-link" aria-label="Поиск по сайту"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><circle cx="10" cy="10" r="6.5"/><path d="m15 15 6 6"/></svg></a><a class="mo-nav-contact" href="<?= $e($href('/contact/')) ?>">Обсудить проект <span aria-hidden="true">↗</span></a></nav></div></header>
        <main id="main">
        <?php if($error): ?><p role="alert" class="mo-alert mo-wrap"><?= $e($error) ?></p><?php endif ?>
        <?php if($mode==='home'):
            $featured=array_values(array_filter($projects,fn($p)=>!empty($p['featured'])));$showcase=($featured?:$projects)[0]??null;
            $hero=($home['cover']??'')?:($showcase['cover']??'');$heroCase=$showcase&&$hero===($showcase['cover']??'')?$showcase:null; ?>
            <section class="mo-wrap mo-hero"><div class="mo-eyebrow"><span>Независимая студия</span><span>Идея / Дизайн / Цифровая среда</span></div><h1><?= $e($tagline) ?></h1><div class="mo-hero-bottom"><p><?= $e(($home['excerpt']??'')?:'Находим суть задачи и превращаем её в ясный визуальный и цифровой опыт.') ?></p><a class="mo-button" href="<?= $e($href('/contact/')) ?>">Обсудить задачу <span aria-hidden="true">↗</span></a><a class="mo-scroll-link" href="#selected-work">Избранные работы ↓</a></div>
            <?php if($hero): ?><figure class="mo-hero-image"><?php if($heroCase): ?><a href="<?= $e($href('/'.$heroCase['slug'].'/')) ?>" aria-label="<?= $e('Открыть кейс: '.$heroCase['title']) ?>"><?php endif ?><?= $image(['cover'=>$hero,'title'=>$home['cover_alt']??$heroCase['title']??'Изображение студии'],true) ?><?php if($heroCase): ?></a><figcaption><span><?= $e($heroCase['title']) ?></span><span>Смотреть кейс ↗</span></figcaption><?php endif ?></figure><?php endif ?></section>
            <?php if($home&&($home['content']||$home['blocks'])): ?><section class="mo-wrap mo-section mo-prose mo-home-content"><?= Content::html($home['content']).Content::blocks($home['blocks']) ?></section><?php endif ?>
            <section id="selected-work" class="mo-section mo-wrap"><div class="mo-section-head"><span class="mo-label">01 / Избранное</span><h2>Смысл становится формой.</h2><a class="mo-text-link" href="<?= $e($href('/projects/')) ?>">Все работы ↗</a></div><div class="mo-work-grid"><?php $projectCards(array_slice($projects,0,4)); ?></div><?php if(!$projects): ?><p class="mo-empty">Работы появятся после публикации проектов.</p><?php endif ?></section>
            <section class="mo-dark"><div class="mo-section mo-wrap"><div class="mo-section-head"><span class="mo-label">02 / Практика</span><h2>От первого вопроса<br>до последней детали.</h2></div><div class="mo-service-list"><?php foreach(array_slice($services,0,4) as $i=>$s): ?><a class="mo-service-row" href="<?= $e($href('/'.$s['slug'].'/')) ?>"><span class="mo-index"><?= str_pad((string)($i+1),2,'0',STR_PAD_LEFT) ?></span><h3><?= $e($s['title']) ?></h3><p><?= $e($s['excerpt']) ?></p><span class="mo-round" aria-hidden="true">↗</span></a><?php endforeach ?></div><?php if(!$services): ?><p class="mo-empty">Направления появятся после публикации услуг.</p><?php endif ?><a class="mo-text-link" href="<?= $e($href('/services/')) ?>">Все услуги ↗</a></div></section>
            <?php if($about): ?><section class="mo-section mo-wrap mo-studio"><span class="mo-label">03 / Подход</span><div><h2><?= $e($about['title']) ?></h2><p><?= $e($about['excerpt']) ?></p><a class="mo-text-link" href="<?= $e($href('/'.$about['slug'].'/')) ?>">Познакомиться со студией ↗</a></div></section><?php endif ?>
            <?php if($team): ?><section class="mo-section mo-wrap"><div class="mo-section-head"><span class="mo-label">04 / Люди</span><h2>Небольшая команда.<br>Общий взгляд.</h2><a class="mo-text-link" href="<?= $e($href('/team/')) ?>">Вся команда ↗</a></div><div class="mo-people-grid"><?php $people(array_slice($team,0,3)); ?></div></section><?php endif ?>
        <?php elseif(in_array($mode,['projects','services','team','search'],true)):
            $rows=$mode==='projects'?$projects:($mode==='services'?$services:($mode==='team'?$team:$pages));
            if($mode==='projects'&&$service)$rows=array_values(array_filter($rows,fn($p)=>(int)($p['parent_id']??0)===$service));
            if($mode==='search'&&$q==='')$rows=[];
            elseif($q!=='')$rows=array_values(array_filter($rows,fn($p)=>$p['slug']!=='home'&&mb_stripos($p['title'].' '.$p['excerpt'].' '.strip_tags($p['content'].' '.Content::blocks($p['blocks'])),$q)!==false));
            if($order==='name')usort($rows,fn($a,$b)=>strcmp(mb_strtolower($a['title']),mb_strtolower($b['title'])));
            if($error)$rows=[];$total=count($rows);$last=max(1,(int)ceil($total/8));$number=min($number,$last);$visible=array_slice($rows,($number-1)*8,8);
            $query=array_filter(['q'=>$q,'order'=>$order==='recent'?'':$order],fn($v)=>$v!==''); ?>
            <section class="mo-wrap mo-section"><?php $crumb(['projects'=>'Работы','services'=>'Услуги','team'=>'Команда','search'=>'Поиск'][$mode]); ?><div class="mo-page-title"><span class="mo-label"><?= $e($name) ?> / <?= $e(['projects'=>'Портфолио','services'=>'Практика','team'=>'Люди','search'=>'Поиск'][$mode]) ?></span><h1><?= $e($title) ?></h1></div>
            <?php if($mode==='projects'): ?><nav class="mo-filters" aria-label="Направления работ"><a href="<?= $e($href('/projects/',$query)) ?>" <?= !$service?'aria-current="page"':'' ?>>Все работы</a><?php foreach($services as $s): ?><a href="<?= $e($href('/projects/',$query+['service'=>$s['id']])) ?>" <?= $service===(int)$s['id']?'aria-current="page"':'' ?>><?= $e($s['title']) ?></a><?php endforeach ?></nav><?php endif ?>
            <?php if(in_array($mode,['search','projects'],true)): ?><form class="mo-search" method="get" action="<?= $e($base.'/'.$mode.'/') ?>"><label>Поисковый запрос<input type="search" name="q" maxlength="100" value="<?= $e($q) ?>" placeholder="Название, услуга или тема"></label><?php if($mode==='projects'): ?><label>Порядок<select name="order"><option value="recent">Сначала новые</option><option value="name" <?= $order==='name'?'selected':'' ?>>По названию</option></select></label><?php if($service): ?><input type="hidden" name="service" value="<?= $service ?>"><?php endif ?><?php endif ?><?php if($snapshot): ?><input type="hidden" name="snapshot" value="<?= $e($snapshot) ?>"><?php endif ?><button class="mo-button">Найти <span aria-hidden="true">↗</span></button><a class="mo-text-link" href="<?= $e($href('/'.$mode.'/')) ?>">Сбросить</a></form><?php endif ?>
            <p class="mo-result-count">Найдено: <?= $total ?></p>
            <?php if($mode==='projects'): ?><div class="mo-work-grid"><?php $projectCards($visible); ?></div>
            <?php elseif($mode==='team'): ?><div class="mo-people-grid"><?php $people($visible); ?></div>
            <?php elseif($mode==='services'): ?><div class="mo-accordions"><?php foreach($visible as $i=>$s): ?><details><summary><span class="mo-index"><?= str_pad((string)(($number-1)*8+$i+1),2,'0',STR_PAD_LEFT) ?></span><h2><?= $e($s['title']) ?></h2><span class="mo-plus" aria-hidden="true">+</span></summary><div class="mo-service-description"><p><?= $e($s['excerpt']) ?></p><?php if(!empty($s['price'])): ?><small><?= $e($s['price']) ?></small><?php endif ?><div class="mo-actions"><a class="mo-text-link" href="<?= $e($href('/'.$s['slug'].'/')) ?>">Состав и этапы ↗</a><a class="mo-button" href="<?= $e($href('/contact/',['service'=>$s['id']])) ?>">Обсудить задачу ↗</a></div></div></details><?php endforeach ?></div>
            <?php else: ?><div class="mo-results"><?php foreach($visible as $p): ?><article><small><?= $e(['service'=>'Услуга','project'=>'Проект','person'=>'Команда','page'=>'Страница'][$p['kind']]) ?></small><h2><a href="<?= $e($href('/'.$p['slug'].'/')) ?>"><?= $e($p['title']) ?> ↗</a></h2><p><?= $e($p['excerpt']) ?></p></article><?php endforeach ?></div><?php endif ?>
            <?php if(!$visible): ?><div class="mo-empty"><h2><?= $mode==='search'&&$q===''?'Что будем искать?':($q!==''?'Ничего не найдено':'Материалы пока не опубликованы') ?></h2><p><?= $q!==''?'Попробуйте другое слово или сбросьте фильтры.':'Выберите раздел или расскажите нам о вашей задаче.' ?></p><a class="mo-text-link" href="<?= $e($href($mode==='projects'?'/projects/':'/contact/')) ?>"><?= $mode==='projects'?'Все работы':'Связаться со студией' ?> ↗</a></div><?php endif ?>
            <?php if($last>1): $numbers=array_unique([1,...range(max(1,$number-2),min($last,$number+2)),$last]); ?><nav class="mo-pagination" aria-label="Страницы"><?php foreach($numbers as $n): ?><a href="<?= $e($href('/'.$mode.'/',$query+array_filter(['service'=>$service,'page'=>$n]))) ?>" <?= $n===$number?'aria-current="page"':'' ?>><?= $n ?></a><?php endforeach ?></nav><?php endif ?></section>
        <?php elseif($mode==='detail'): $type=$page['kind'];$section=['project'=>'projects','service'=>'services','person'=>'team','page'=>null][$type]; ?>
            <article class="mo-wrap mo-section mo-detail mo-detail-<?= $e($type) ?>"><?php $crumb($page['title'],$section); ?><div class="mo-page-title"><span class="mo-label"><?= $e(['project'=>'Кейс','service'=>'Услуга','person'=>'Команда','page'=>'Информация'][$type]) ?></span><h1><?= $e($page['title']) ?></h1><p><?= $e($page['excerpt']) ?></p></div>
            <?php if($page['cover']): ?><figure class="mo-detail-image"><a href="<?= $e(Content::asset(Content::imageUrl($page['cover']))) ?>" target="_blank" rel="noopener" aria-label="<?= $e('Открыть изображение: '.$page['title']) ?>"><?= $image($page,true) ?><span class="mo-round" aria-hidden="true">↗</span></a><?php if(!empty($page['cover_alt'])): ?><figcaption><?= $e($page['cover_alt']) ?></figcaption><?php endif ?></figure><?php elseif($type==='person'): ?><div class="mo-profile-monogram" aria-hidden="true"><?= $e(self::initials($page['title'])) ?></div><?php endif ?>
            <div class="mo-detail-body"><aside class="mo-detail-meta"><?php foreach(['client'=>'Клиент / контекст','year'=>'Год / этап','location'=>'Направление','role'=>'Роль','price'=>'Условия'] as $key=>$label)if(!empty($page[$key])): ?><div><small><?= $label ?></small><p><?= $e($page[$key]) ?></p></div><?php endif ?><?php foreach($services as $s)if((int)$s['id']===(int)($page['parent_id']??0)): ?><div><small>Связанная услуга</small><a class="mo-text-link" href="<?= $e($href('/'.$s['slug'].'/')) ?>"><?= $e($s['title']) ?> ↗</a></div><?php endif ?><?php foreach($team as $person)if((int)$person['id']===(int)($page['person_id']??0)): ?><div><small>Команда проекта</small><a class="mo-text-link" href="<?= $e($href('/'.$person['slug'].'/')) ?>"><?= $e($person['title']) ?> ↗</a></div><?php endif ?><?php if($type!=='page'): ?><a class="mo-button" href="<?= $e($href('/contact/',$type==='project'?array_filter(['project'=>$page['id'],'service'=>$page['parent_id']??0]):($type==='service'?['service'=>$page['id']]:[]))) ?>">Обсудить задачу ↗</a><?php endif ?></aside><div class="mo-prose"><?= Content::html($page['content']).Content::blocks($page['blocks']) ?></div></div></article>
            <?php $related=array_values(array_filter($projects,fn($p)=>(int)$p['id']!==(int)$page['id']&&($type==='service'?(int)($p['parent_id']??0)===(int)$page['id']:($type==='person'?(int)($p['person_id']??0)===(int)$page['id']:($type==='project'&&!empty($page['parent_id'])&&(int)($p['parent_id']??0)===(int)$page['parent_id'])))));if($related): ?><section class="mo-wrap mo-section"><div class="mo-section-head"><span class="mo-label">Связанные работы</span><h2>Продолжение темы.</h2></div><div class="mo-work-grid"><?php $projectCards(array_slice($related,0,2)); ?></div></section><?php endif ?>
        <?php elseif($mode==='contact'): ?><section class="mo-wrap mo-section"><?php $crumb('Контакты'); ?><div class="mo-contact"><div><span class="mo-label">Задача начинается с вопроса</span><h1><?= $e($title) ?></h1><p>Расскажите, что хотите изменить.<br>Оставьте email или телефон для ответа.</p><div class="mo-contact-links"><?php foreach(['email'=>'mailto:','phone'=>'tel:'] as $key=>$prefix)if(!empty($settings[$key])): ?><a href="<?= $e($prefix.preg_replace($key==='phone'?'/[^+0-9]/':'/\s/','',$settings[$key])) ?>"><?= $e($settings[$key]) ?></a><?php endif ?><?php if($privacy): ?><a class="mo-text-link" href="<?= $e($href('/privacy/')) ?>">Обработка данных ↗</a><?php endif ?></div></div><div class="mo-form"><?= $options['form']??'<h2>Свяжитесь напрямую</h2><p>Форма временно недоступна. Используйте контакты студии.</p>' ?></div></div></section>
        <?php elseif($mode==='success'): ?><section class="mo-wrap mo-section mo-success"><span class="mo-success-icon" aria-hidden="true">↗</span><small class="mo-label"><?= !empty($options['demo'])?'Тестовая заявка':'Обращение сохранено' ?></small><h1>Спасибо.<br>Начало положено.</h1><p>Номер заявки: <strong><?= $e($options['receipt']) ?></strong></p><p><?= !empty($options['demo'])?'Это демонстрация. Подтверждение доступно только в вашей сессии. Письма не отправлялись, контакты не сохранялись в CRM.':'Заявка сохранена. Уведомление для команды поставлено в очередь; это не означает, что сотрудник уже прочитал обращение.' ?></p><div class="mo-actions"><a class="mo-button" href="<?= $e($href('/projects/')) ?>">Посмотреть работы ↗</a><a class="mo-text-link" href="<?= $e($href('/')) ?>">На главную</a></div></section>
        <?php else: ?><section class="mo-wrap mo-section mo-notfound"><span class="mo-label">404 / Страница не найдена</span><h1>Здесь пока пусто.</h1><p>Адрес изменился или материал ещё не опубликован.</p><a class="mo-button" href="<?= $e($href('/projects/')) ?>">Перейти к работам ↗</a></section><?php endif ?>
        <?php if(!in_array($mode,['contact','success','404'],true)): ?><section class="mo-wrap mo-outro"><span class="mo-label">Следующий шаг</span><a href="<?= $e($href('/contact/',$page&&$page['kind']==='service'?['service'=>$page['id']]:[])) ?>"><h2>Есть задача?<br>Давайте обсудим.</h2><span class="mo-outro-arrow" aria-hidden="true">↗</span></a></section><?php endif ?></main>
        <footer class="mo-footer mo-wrap"><div><a class="mo-logo" href="<?= $e($href('/')) ?>"><?= $e($name) ?></a><p><?= $e($tagline) ?></p></div><nav aria-label="Информация"><a href="<?= $e($href('/contact/')) ?>">Контакты</a><a href="<?= $e($href('/search/')) ?>">Поиск</a><?php if($privacy): ?><a href="<?= $e($href('/privacy/')) ?>">Обработка данных</a><?php endif ?><?= Journal::menu($settings['footer_menu']??[]) ?></nav><div class="mo-footer-bottom"><span>© <?= gmdate('Y') ?> <?= $e($name) ?></span><span><?= !empty($options['demo'])?'Вымышленная студия и иллюстративные проекты':'BYPCMS Business / Mono' ?></span></div></footer></body></html><?php
    }
